--- FILE: src/agent/index.ts ---
Range: 1 - 337

1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  * 
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, ToolSchema } from "../providers/base";
10 | import { ScopedLogger } from "../util/log";
11 | import { formatToolResult } from "../util/log-format";
12 | import { SessionManager } from "../session-v2";
13 | import { SYSTEM_PROMPT } from "../prompts/system";
14 | import { ToolRegistry } from "../tool/registry";
15 | 
16 | export interface AgentConfig {
17 |     llmProvider: LLMProvider;
18 |     sessionManager: SessionManager;
19 |     systemPrompt: string;
20 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
21 |     defaultTools?: ToolSchema[];
22 |     /** 最大循环次数，防止无限循环，默认 10 */
23 |     maxLoop?: number;
24 |     /** 最大 token 数，默认 8000 */
25 |     maxTokens?: number;
26 |     /** 最大输出 token 数，默认 8000 */
27 |     maxOutputTokens?: number;
28 |     /** 工具并发上限，默认 4 */
29 |     toolConcurrency?: number;
30 |     /** 单次工具调用超时（毫秒），默认 120000 */
31 |     toolTimeoutMs?: number;
32 |     /** 连续重复的工具调用轮次上限，默认 2 */
33 |     noProgressLimit?: number;
34 | }
35 | 
36 | export interface AgentResponse {
37 |     content: string;
38 |     role: 'assistant';
39 | }
40 | 
41 | export default class Agent extends EventEmitter {
42 |     private llmProvider: LLMProvider;
43 |     private logger: ScopedLogger;
44 |     private sessionManager: SessionManager;
45 |     private systemPrompt: string;
46 |     private defaultTools: ToolSchema[] | undefined;
47 |     private maxLoop: number;
48 |     maxOutputTokens: number;
49 |     maxTokens: number;
50 |     private toolConcurrency: number;
51 |     private toolTimeoutMs: number;
52 |     private noProgressLimit: number;
53 |     constructor(config: AgentConfig) {
54 |         super();
55 |         this.llmProvider = config.llmProvider;
56 |         this.sessionManager = config.sessionManager;
57 |         this.systemPrompt = config.systemPrompt;
58 |         this.defaultTools = config.defaultTools;
59 |         this.logger = new ScopedLogger('Agent');
60 |         this.maxLoop = config.maxLoop ?? 1024;
61 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
62 |         const providerMaxTokens = this.llmProvider.maxTokens;
63 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
64 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
65 |         this.toolConcurrency = Math.max(1, config.toolConcurrency ?? 4);
66 |         this.toolTimeoutMs = config.toolTimeoutMs ?? 120000;
67 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
68 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
69 |         this.sessionManager.maxTokens = this.maxTokens;
70 |     }
71 | 
72 |     private async withTimeout<T>(promise: Promise<T>, timeoutMs: number, timeoutMessage: string): Promise<T> {
73 |         if (!timeoutMs || timeoutMs <= 0) {
74 |             return promise;
75 |         }
76 | 
77 |         let timeoutId: ReturnType<typeof setTimeout> | undefined;
78 |         const timeoutPromise = new Promise<never>((_, reject) => {
79 |             timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
80 |         });
81 | 
82 |         return Promise.race([promise, timeoutPromise]).finally(() => {
83 |             if (timeoutId) {
84 |                 clearTimeout(timeoutId);
85 |             }
86 |         });
87 |     }
88 | 
89 |     private async runWithConcurrency<T, R>(
90 |         items: T[],
91 |         limit: number,
92 |         task: (item: T, index: number) => Promise<R>
93 |     ): Promise<R[]> {
94 |         if (items.length === 0) {
95 |             return [];
96 |         }
97 | 
98 |         if (limit <= 1) {
99 |             const results: R[] = [];
100 |             for (let i = 0; i < items.length; i++) {
101 |                 results.push(await task(items[i], i));
102 |             }
103 |             return results;
104 |         }
105 | 
106 |         const results = new Array<R>(items.length);
107 |         let nextIndex = 0;
108 |         const workerCount = Math.min(limit, items.length);
109 | 
110 |         const workers = Array.from({ length: workerCount }, async () => {
111 |             while (true) {
112 |                 const currentIndex = nextIndex++;
113 |                 if (currentIndex >= items.length) {
114 |                     break;
115 |                 }
116 |                 results[currentIndex] = await task(items[currentIndex], currentIndex);
117 |             }
118 |         });
119 | 
120 |         await Promise.all(workers);
121 |         return results;
122 |     }
123 | 
124 |     private buildToolSignature(toolCalls: NonNullable<LLMResponse['tool_calls']>): string {
125 |         try {
126 |             return JSON.stringify(
127 |                 toolCalls.map((call) => ({
128 |                     name: call.function.name,
129 |                     arguments: call.function.arguments,
130 |                 }))
131 |             );
132 |         } catch (_) {
133 |             return '';
134 |         }
135 |     }
136 | 
137 |     /**
138 |      * 运行 Agent 处理用户查询
139 |      * @param sessionId 会话 ID
140 |      * @param userId 用户 ID
141 |      * @param query 用户查询
142 |      * @param options 选项
143 |      * @returns Agent 响应
144 |      */
145 |     async run(
146 |         query: string,
147 |         options?: { silent?: boolean; tools?: ToolSchema[] }
148 |     ): Promise<AgentResponse | null> {
149 | 
150 |      
151 |         try {
152 | 
153 |             // 3. 获取工具 schemas（优先级：传入参数 > 默认配置 > ToolRegistry 全部）
154 |             const tools = options?.tools ?? this.defaultTools ?? ToolRegistry.getSchemas();
155 | 
156 |             // 4. LLM 调用循环（处理工具调用）
157 |             let i = 0; // 防止无限循环
158 |             let finalResponse: AgentResponse | null = null;
159 |             let lastToolSignature: string | null = null;
160 |             let repeatedToolCalls = 0;
161 |   
162 |   
163 |             this.sessionManager.addMessage({
164 |                 role: 'user',
165 |                 type: 'text',
166 |                 content: query
167 |             });
168 | 
169 |             while (i < this.maxLoop) {
170 |                 i++; // 在循环开始时递增计数器
171 | 
172 |                 const llmMessages = await this.sessionManager.getMessages();
173 | 
174 |                 const spinner = this.logger.spinner(`Thinking-${i}...`);
175 |                 let llmResponse: Awaited<ReturnType<LLMProvider['generate']>> = null;
176 |                 try {
177 |                     // 调用 LLM
178 |                     llmResponse = await this.llmProvider.generate([
179 |                         {
180 |                             role: 'system',
181 |                             content: this.systemPrompt,
182 |                         },
183 |                         ...llmMessages
184 |                     ], {
185 |                         model: process.env.AI_MODEL,
186 |                         tools: tools.length > 0 ? tools : undefined,
187 |                         max_tokens: this.maxOutputTokens,
188 |                     });
189 |                     console.log( this.systemPrompt)
190 |                 } catch (error) {
191 |                     const errorMsg = error instanceof Error ? error.message : String(error);
192 |                     spinner.fail(`Thinking-${i} failed`);
193 |                     this.emit('failure', { error: errorMsg });
194 |                     this.logger.error(`LLM error: ${errorMsg}`);
195 |                     return null;
196 |                 }
197 | 
198 |                 if (!llmResponse) {
199 |                     this.emit('failure', {error: 'LLM returned null response' });
200 |                     this.logger.error("LLM error")
201 |                     spinner.fail(`Thinking-${i} failed`);
202 |                     return null;
203 |                 }
204 |                 spinner.succeed(`Thinking-${i} end`);
205 | 
206 |                 // 检查是否有工具调用
207 |                 if (llmResponse.tool_calls && llmResponse.tool_calls.length > 0) {
208 |                     const toolSignature = this.buildToolSignature(llmResponse.tool_calls);
209 |                     if (toolSignature && toolSignature === lastToolSignature) {
210 |                         repeatedToolCalls += 1;
211 |                     } else {
212 |                         repeatedToolCalls = 0;
213 |                         lastToolSignature = toolSignature;
214 |                     }
215 | 
216 |                     if (this.noProgressLimit > 0 && repeatedToolCalls >= this.noProgressLimit) {
217 |                         const errorMsg = `Repeated tool_calls detected for ${this.noProgressLimit + 1} iterations, aborting to prevent loop.`;
218 |                         this.logger.error(errorMsg);
219 |                         this.emit('failure', { error: errorMsg });
220 |                         return null;
221 |                     }
222 | 
223 |                     // 添加 assistant 消息（包含 tool_calls）
224 |                     this.sessionManager.addMessage({
225 |                         role: 'assistant',
226 |                         content: llmResponse.content,
227 |                         type: 'tool_call',
228 |                         tool_calls: llmResponse.tool_calls,
229 |                     });
230 | 
231 |                     this.logger.info(`Tool tips: ${llmResponse.content}`);
232 | 
233 |                     const toolCalls = llmResponse.tool_calls;
234 |                     const toolConcurrency = Math.min(this.toolConcurrency, toolCalls.length);
235 | 
236 |                     const results = await this.runWithConcurrency(toolCalls, toolConcurrency, async (toolCall) => {
237 |                         const { id,function: fn } = toolCall;
238 |                         try {
239 |                             // 解析参数（带容错处理）
240 |                             let args: unknown;
241 |                             try {
242 |                                 args = JSON.parse(fn.arguments);
243 |                             } catch (parseError) {
244 |                                 // JSON 解析失败 - 记录详细信息并返回友好的错误信息
245 |                                 const truncatedArgs = fn.arguments.length > 200
246 |                                     ? fn.arguments.slice(0, 200) + '...'
247 |                                     : fn.arguments;
248 |                                 const parseErrorMsg = parseError instanceof Error ? parseError.message : String(parseError);
249 |                                 const errorMsg = `Invalid JSON in tool parameters: ${parseErrorMsg}\nReceived: ${truncatedArgs}`;
250 |                                 this.logger.error(errorMsg);
251 |                                 return {
252 |                                     toolCall,
253 |                                     result: `Error: Failed to parse tool arguments. The JSON was malformed. Please try again with properly formatted parameters.`,
254 |                                     error: errorMsg,
255 |                                     id,
256 |                                 };
257 |                             }
258 | 
259 |                             const spinner = this.logger.spinner(`Tool ${fn.name}(...)`);
260 |                             // 执行工具
261 |                             let result: string;
262 |                             try {
263 |                                 result = await this.withTimeout(
264 |                                     ToolRegistry.execute(fn.name, args),
265 |                                     this.toolTimeoutMs,
266 |                                     `Tool ${fn.name} timed out after ${this.toolTimeoutMs}ms`
267 |                                 );
268 |                                 spinner.succeed(`Tool ${fn.name} completed`);
269 |                             } catch (error) {
270 |                                 spinner.fail(`Tool ${fn.name} failed`);
271 |                                 throw error;
272 |                             }
273 | 
274 |                             if (!options?.silent) {
275 |                                 this.logger.info(`Tool ${fn.name} result: ${formatToolResult(fn.name, result)}`);
276 |                             }
277 | 
278 |                             // 返回成功结果
279 |                             return { toolCall, result, error: undefined ,id};
280 |                         } catch (error) {
281 |                             const errorMsg = error instanceof Error ? error.message : String(error);
282 |                             this.logger.error(`Tool execution error: ${errorMsg}`);
283 | 
284 |                             // 返回错误结果
285 |                             return { toolCall, result: `Error: ${errorMsg}`, error: errorMsg,id };
286 |                         }
287 |                     });
288 | 
289 |                     // 按原始顺序添加工具结果消息
290 |                     for (const { toolCall, result, error: _error } of results) {
291 |                         const { id } = toolCall;
292 | 
293 |                         this.sessionManager.addMessage({
294 |                             role: 'tool',
295 |                             content: result,
296 |                             type: 'tool',
297 |                             tool_call_id: id,
298 |                         });
299 |                     }
300 | 
301 |                     // 继续循环，让 LLM 基于工具结果生成响应
302 |                     continue;
303 |                 }
304 | 
305 |                 // 没有工具调用，这是最终响应
306 |                 this.sessionManager.addMessage({
307 |                     role: 'assistant',
308 |                     type: 'text',
309 |                     content: llmResponse.content,
310 |                 });
311 | 
312 |                 finalResponse = {
313 |                     content: llmResponse.content,
314 |                     role: 'assistant',
315 |                 };
316 | 
317 |                 break;
318 |             }
319 | 
320 |             if (i >= this.maxLoop) {
321 |                 this.logger.error('Max iterations reached, possible infinite loop');
322 |                 return null;
323 |             }
324 | 
325 |     
326 | 
327 |             return finalResponse;
328 | 
329 |         } catch (error) {
330 |             const errorMsg = error instanceof Error ? error.message : String(error);
331 |             this.logger.error(`Agent error: ${errorMsg}`);
332 |             return null;
333 |         }
334 |     }
335 | 
336 | }
