--- FILE: src/tool/registry.ts ---
Range: 1 - 287

1 | import { BaseTool } from "./base";
2 | 
3 | /**
4 |  * 工具注册表类
5 |  *
6 |  * 单例模式，管理所有可用的工具
7 |  */
8 | export class ToolRegistry {
9 |     /** 已注册的工具映射 */
10 |     private static tools: Map<string, BaseTool<any>> = new Map();
11 |     private static context: { sessionId?: string; sessionPath?: string } = {};
12 | 
13 |     /** 私有构造函数，防止外部实例化 */
14 |     private constructor() {}
15 | 
16 |     /**
17 |      * 注册工具
18 |      *
19 |      * 支持单个工具或工具数组
20 |      *
21 |      * @param tool - 工具实例或工具数组
22 |      * @throws 如果工具名称已存在
23 |      *
24 |      * @example
25 |      * ```ts
26 |      * // 注册单个工具
27 |      * ToolRegistry.register(new BashTool());
28 |      *
29 |      * // 批量注册工具
30 |      * ToolRegistry.register([new BashTool(), new GrepTool()]);
31 |      * ```
32 |      */
33 |     static register<T extends BaseTool<any>>(tool: T | T[]): void {
34 |         const tools = Array.isArray(tool) ? tool : [tool];
35 |         for (const t of tools) {
36 |             if (this.tools.has(t.name)) {
37 |                 throw new Error(`Tool "${t.name}" is already registered`);
38 |             }
39 |             this.tools.set(t.name, t);
40 |         }
41 |     }
42 | 
43 |     /**
44 |      * 注销工具
45 |      *
46 |      * @param name - 工具名称
47 |      * @returns 是否成功注销
48 |      */
49 |     static unregister(name: string): boolean {
50 |         return this.tools.delete(name);
51 |     }
52 | 
53 |     /**
54 |      * 根据名称获取工具
55 |      *
56 |      * @param name - 工具名称
57 |      * @returns 工具实例，如果不存在则返回 undefined
58 |      */
59 |     static get<T extends BaseTool<any> = BaseTool<any>>(name: string): T | undefined {
60 |         return this.tools.get(name) as T | undefined;
61 |     }
62 | 
63 |     /**
64 |      * 获取所有已注册的工具
65 |      *
66 |      * @returns 工具实例数组
67 |      */
68 |     static getAll(): BaseTool<any>[] {
69 |         return Array.from(this.tools.values());
70 |     }
71 | 
72 |     /**
73 |      * 获取所有工具的名称
74 |      *
75 |      * @returns 工具名称数组
76 |      */
77 |     static getNames(): string[] {
78 |         return Array.from(this.tools.keys());
79 |     }
80 | 
81 |     /**
82 |      * 检查工具是否已注册
83 |      *
84 |      * @param name - 工具名称
85 |      * @returns 是否已注册
86 |      */
87 |     static has(name: string): boolean {
88 |         return this.tools.has(name);
89 |     }
90 | 
91 |     /**
92 |      * 获取已注册工具的数量
93 |      *
94 |      * @returns 工具数量
95 |      */
96 |     static get size(): number {
97 |         return this.tools.size;
98 |     }
99 | 
100 |     /**
101 |      * 清空所有已注册的工具
102 |      *
103 |      * @warning 这通常只在测试中使用
104 |      */
105 |     static clear(): void {
106 |         this.tools.clear();
107 |     }
108 | 
109 |     static setContext(context: { sessionId?: string; sessionPath?: string }): void {
110 |         this.context = { ...this.context, ...context };
111 |     }
112 | 
113 |     static getContext(): { sessionId?: string; sessionPath?: string } {
114 |         return this.context;
115 |     }
116 | 
117 |     /**
118 |      * 执行指定工具
119 |      *
120 |      * @param name - 工具名称
121 |      * @param args - 工具参数
122 |      * @returns 执行结果
123 |      * @throws 如果工具不存在或参数无效
124 |      */
125 |     static async execute(name: string, args: unknown): Promise<string> {
126 |         const tool = this.get(name);
127 |         if (!tool) {
128 |             return `Tool "${name}" not found`;
129 |         }
130 | 
131 |         // 验证参数
132 |         const parsed = tool.schema.safeParse(args);
133 | 
134 |         if (!parsed.success) {
135 |             return `Invalid arguments for tool "${name}": ${parsed.error.errors.map((e: { message: string }) => e.message).join(', ')}`;
136 |         }
137 | 
138 |         return await tool.execute(parsed.data);
139 |     }
140 | 
141 |     /**
142 |      * 获取工具的 schema（用于 LLM 函数调用）
143 |      *
144 |      * 返回符合 OpenAI function calling 格式：
145 |      * https://platform.openai.com/docs/guides/function-calling
146 |      *
147 |      * @returns 所有工具的 schema 数组
148 |      */
149 |     static getSchemas(): Array<{
150 |         type: 'function';
151 |         function: {
152 |             name: string;
153 |             description: string;
154 |             strict?: boolean;
155 |             parameters: Record<string, unknown>;
156 |         };
157 |     }> {
158 |         return this.getAll().map(tool => {
159 |             // 将 zod schema 转换为 JSON Schema 格式
160 |             const zodSchema = tool.schema;
161 |             const jsonSchema = this.zodToJsonSchema(zodSchema);
162 | 
163 |             return {
164 |                 type: 'function',
165 |                 function: {
166 |                     name: tool.name,
167 |                     description: tool.description,
168 |                     strict: true,
169 |                     parameters: jsonSchema,
170 |                 },
171 |             };
172 |         });
173 |     }
174 | 
175 |     /**
176 |      * 将 Zod schema 转换为 JSON Schema 格式
177 |      *
178 |      * @param schema - Zod schema
179 |      * @returns JSON Schema 对象
180 |      */
181 |     private static zodToJsonSchema(schema: any): Record<string, unknown> {
182 |         // 基础实现，处理常见类型
183 |         if (schema._def?.typeName === 'ZodObject') {
184 |             const shape = schema._def.shape();
185 |             const properties: Record<string, unknown> = {};
186 |             const required: string[] = [];
187 | 
188 |             for (const [key, value] of Object.entries(shape)) {
189 |                 const def = (value as any)._def;
190 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
191 | 
192 |                 // 检查是否是可选字段
193 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
194 |                                    (value as any).isOptional?.();
195 |                 if (!isOptional) {
196 |                     required.push(key);
197 |                 }
198 |             }
199 | 
200 |             return {
201 |                 type: 'object',
202 |                 properties,
203 |                 required: required.length > 0 ? required : undefined,
204 |                 additionalProperties: false,
205 |             };
206 |         }
207 | 
208 |         return { type: 'object', properties: {}, additionalProperties: false };
209 |     }
210 | 
211 |     /**
212 |      * 将 Zod 类型转换为 JSON Schema 类型
213 |      *
214 |      * @param def - Zod 类型定义
215 |      * @param key - 字段名（用于错误信息）
216 |      * @returns JSON Schema 类型定义
217 |      */
218 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
219 |         const typeName = def?.typeName;
220 | 
221 |         switch (typeName) {
222 |             case 'ZodString':
223 |                 return { type: 'string' };
224 | 
225 |             case 'ZodNumber':
226 |                 return { type: 'number' };
227 | 
228 |             case 'ZodBoolean':
229 |                 return { type: 'boolean' };
230 | 
231 |             case 'ZodNull':
232 |                 return { type: 'null' };
233 | 
234 |             case 'ZodArray':
235 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
236 |                 return {
237 |                     type: 'array',
238 |                     items: itemType,
239 |                 };
240 | 
241 |             case 'ZodObject':
242 |                 return this.zodToJsonSchema({ _def: def });
243 | 
244 |             case 'ZodOptional':
245 |             case 'ZodNullable':
246 |             case 'ZodDefault':
247 |                 // innerType 是 Zod 对象，需要获取其 _def
248 |                 return this.zodTypeToJsonSchema(def.innerType._def, key);
249 | 
250 |             case 'ZodEnum':
251 |                 return {
252 |                     type: 'string',
253 |                     enum: def.values,
254 |                 };
255 | 
256 |             case 'ZodLiteral':
257 |                 return {
258 |                     type: typeof def.value,
259 |                     const: def.value,
260 |                 };
261 | 
262 |             case 'ZodUnion':
263 |             case 'ZodDiscriminatedUnion':
264 |                 return {
265 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
266 |                 };
267 | 
268 |             case 'ZodEffects':
269 |                 // 处理带描述的字段
270 |                 const innerSchema = this.zodTypeToJsonSchema(def.innerType._def, key);
271 |                 if (def.description) {
272 |                     return { ...innerSchema, description: def.description };
273 |                 }
274 |                 return innerSchema;
275 | 
276 |             default:
277 |                 // 未知类型，使用 any
278 |                 if (typeName !== undefined) {
279 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
280 |                 } else {
281 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
282 |                 }
283 |                 return {};
284 |         }
285 |     }
286 | }
